create type public.app_role as enum ('admin', 'user');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id,role));
grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create function public.has_role(_user_id uuid, _role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy "Read own roles" on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.assign_publisher_role() returns trigger language plpgsql security definer set search_path=public as $$ begin if lower(new.email)='drishtikalra1@gmail.com' and new.email_confirmed_at is not null then insert into public.user_roles(user_id,role) values(new.id,'admin') on conflict do nothing; end if; return new; end $$;
create trigger assign_publisher after insert or update of email_confirmed_at,email on auth.users for each row execute function public.assign_publisher_role();
create table public.posts (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, kind text not null default 'article' check(kind in ('article','carousel','video')), category text not null default 'UPSC', excerpt text not null default '', body text not null default '', media text[] not null default '{}', youtube_id text not null default '', status text not null default 'draft' check(status in ('draft','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select on public.posts to anon;
grant select,insert,update,delete on public.posts to authenticated;
grant all on public.posts to service_role;
alter table public.posts enable row level security;
create policy "Published posts are public" on public.posts for select to anon,authenticated using(status='published');
create policy "Publisher manages all posts" on public.posts for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create index posts_public_listing on public.posts(status,created_at desc);
create policy "Readers access published images" on storage.objects for select to anon,authenticated using(bucket_id='publication-media' and exists(select 1 from public.posts where status='published' and name=any(media)));
create policy "Publisher manages images" on storage.objects for all to authenticated using(bucket_id='publication-media' and public.has_role(auth.uid(),'admin')) with check(bucket_id='publication-media' and public.has_role(auth.uid(),'admin'));